 app.querySelectorAll('[data-savitch-advance]').forEach(b=>b.onclick=()=>{const count=Number(b.dataset.savitchAdvance);savitchAdvance(q,count);update();(app.querySelector(`[data-savitch-advance="${count}"]:not(:disabled)`)||app.querySelector('#savitch-reset-case')).focus();});
