 app.querySelector('#little-check').onclick=()=>{s.checked=true;writeDraft(active.id,s);if(littleComplete(s)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderLittle();app.querySelector('#little-check').focus();};
