  app.querySelectorAll('[data-tess-vertex]').forEach(b=>b.onclick=()=>{const vertex=b.dataset.tessVertex;tessellationQuest.trials[id]=tessStep(tessellationQuest.trials[id],vertex);persist();if(tessComplete(tessellationQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderTessellation();app.querySelector('#reset-tess-case').focus();});
