  app.querySelectorAll('[data-component-cell]').forEach(b=>b.onclick=()=>{const key=b.dataset.componentCell;if(!componentPixels.includes(key))return;c.selected=c.selected.includes(key)?c.selected.filter(x=>x!==key):[...c.selected,key];c.checked=false;persist();renderComponents();app.querySelector(`[data-component-cell="${key}"]`).focus();});
  app.querySelectorAll('[data-component-count]').forEach(b=>b.onclick=()=>{c.count=Number(b.dataset.componentCount);c.checked=false;persist();renderComponents();app.querySelector(`[data-component-count="${c.count}"]`).focus();});
  app.querySelector('#check-components').onclick=()=>{c.checked=true;persist();if(componentsComplete(componentsQuest)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderComponents();app.querySelector('#check-components').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
