 app.querySelectorAll('[data-pc-guidance]').forEach(b=>b.onclick=()=>{t.guidance=b.dataset.pcGuidance;t.checked=false;codeQuestMessage='';update();app.querySelector('[data-pc-guidance="'+t.guidance+'"]').focus();});
 app.querySelectorAll('[data-pc-unknown]').forEach(b=>b.onclick=()=>{t.unknown=b.dataset.pcUnknown;t.checked=false;codeQuestMessage='';update();app.querySelector('[data-pc-unknown="'+t.unknown+'"]').focus();});
 app.querySelectorAll('[data-pc-action]').forEach(b=>b.onclick=()=>{t.action=b.dataset.pcAction;t.checked=false;codeQuestMessage='';update();app.querySelector('[data-pc-action="'+t.action+'"]').focus();});
 app.querySelector('#pc-check').onclick=()=>{if(codeQuestCheck(q))codeQuestMessage='原則、未確認の事実と次の行動を選びました。';else{const labels={guidance:'原則',unknown:'未確認の事実',action:'次の行動'};codeQuestMessage='見直すところ：'+codeQuestIssues(q.selected,t).map(k=>labels[k]).join('、')+'。';}update();app.querySelector('#pc-check').focus();};
