let accountabilityQuest,accountabilityMessage='',accountabilityRecordMessage='';
function renderAccountability(){
 const q=accountabilityQuest,t=q.trials[q.selected],stage=accountabilityStages[q.selected],done=accountabilityDone(q);
 const stages=Object.entries(accountabilityStages).map(([k,v])=>'<button data-da-stage="'+k+'" aria-pressed="'+(q.selected===k)+'">'+v.name+(q.trials[k].checked?' ✓':'')+'</button>').join('');
 const roles=Object.entries(accountabilityRoles).map(([k,v])=>'<button data-da-role="'+k+'" aria-pressed="'+(t.role===k)+'">'+v+'</button>').join('');
 const actions=Object.entries(accountabilityActions).map(([k,v])=>'<button data-da-action="'+k+'" aria-pressed="'+(t.action===k)+'">'+v+'</button>').join('');
 const recordControls=Object.entries(accountabilityRecordOptions).map(([key,o])=>'<h3>'+o.name+'</h3><div class="scenario-selector" role="group" aria-label="記録の'+o.name+'">'+Object.entries(o.choices).map(([value,label])=>'<button data-da-record-key="'+key+'" data-da-record-value="'+value+'" aria-pressed="'+(q.record[key]===value)+'">'+label+'</button>').join('')+'</div>').join('');
 app.innerHTML='<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST '+active.number+' ／ '+active.tag+'</div><h1>'+active.title+'</h1><p>'+active.story+'</p></div></div><section class="panel"><h2>受付の担当を決める</h2>'+draftMessage()+'<p>依頼1113で配達に必要な項目を選びました。今回は、その受付の設計・承認・運用を通じて、誰が何を確認するか考えます。実際の組織には様々な役割分担がありますが、ここでは下に示す架空の分担を使います。</p><p>設計係は項目を設計し、ギルドは受付を運営して承認し、運用係は利用中の問題を報告します。各場面で担当と行動を選んで確かめましょう。</p><div class="scenario-selector" role="group" aria-label="確認する段階">'+stages+'</div><p><strong>'+stage.name+'：</strong>'+stage.story+'</p><h3>担当</h3><div class="scenario-selector" role="group" aria-label="担当">'+roles+'</div><h3>確認する行動</h3><div class="scenario-selector" role="group" aria-label="行動">'+actions+'</div><button id="da-check">担当と行動を確かめる</button><p role="status">'+accountabilityMessage+'</p><details><summary>手がかり</summary><p>設計では項目と目的、承認では判断の記録、運用では問題の報告と見直しを考えましょう。</p></details></section><section class="panel"><h2>判断の記録を組み立てる</h2><p>この受付は品物の配達だけを行い、宛名と配達先を使います。年齢条件はありません。目的、項目、見直しを記録に残し、承認の前に確かめましょう。</p>'+recordControls+'<button id="da-record-check">記録を確かめる</button><p id="da-record-status" role="status">'+accountabilityRecordMessage+'</p><p>これは判断を整理するための固定例で、法令が求める記録のすべてではありません。</p></section><section class="panel"><h2>責任と法的な枠組み</h2><p>たとえば EU の一般データ保護規則（GDPR）では、適用される場合、管理者は個人データの処理原則を守り、その遵守を示す責任を負います。設計時から必要な保護を考えることも求められます。どの法律が適用されるかは状況によって異なります。</p><p>この受付の運営について、適切な考え方は？</p><div class="scenario-selector" role="group" aria-label="責任の振り返り"><button data-da-reflection="ongoing" aria-pressed="'+(q.reflection==='ongoing')+'">担当を分けても、ギルドは記録や運用を見直す責任を持つ</button><button data-da-reflection="delegated" aria-pressed="'+(q.reflection==='delegated')+'">運用係に任せたら、ギルドは以後の問題を確認しなくてよい</button></div>'+(q.reflection==='delegated'?'<p>役割を分けても、運営する組織は問題の報告を受け、必要な対応を判断します。</p>':'')+'</section>'+(done?'<section class="result panel"><h2>受付の確認手順を整えました！</h2><p>必要な項目の検討、判断の記録、運用後の見直しを担当と結びつけました。法的な役割や義務は具体的な処理と適用される法令によって異なります。</p><p>これは架空の分担と GDPR の原則の一例で、実際の法令適用や適合を判定しません。</p><button id="return">ギルドへ戻る</button></section>':'')+'<aside class="reference">学びの手がかり：<a href="https://commission.europa.eu/law/law-topic/data-protection/information-business-and-organisations/principles-gdpr_en" target="_blank" rel="noopener noreferrer">欧州委員会：GDPR の原則 ↗</a> ／ <a href="https://www.acm.org/binaries/content/assets/about/acm-code-of-ethics-booklet.pdf" target="_blank" rel="noopener noreferrer">ACM：倫理規範 ↗</a></aside></div>';
 const update=()=>{writeDraft(active.id,q);if(accountabilityDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderAccountability();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);accountabilityQuest=accountabilityCreate();accountabilityMessage='';accountabilityRecordMessage='';renderAccountability();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-da-stage]').forEach(b=>b.onclick=()=>{q.selected=b.dataset.daStage;accountabilityMessage='';update();app.querySelector('[data-da-stage="'+q.selected+'"]').focus();});
 app.querySelectorAll('[data-da-role]').forEach(b=>b.onclick=()=>{t.role=b.dataset.daRole;t.checked=false;accountabilityMessage='';update();app.querySelector('[data-da-role="'+t.role+'"]').focus();});
 app.querySelectorAll('[data-da-action]').forEach(b=>b.onclick=()=>{t.action=b.dataset.daAction;t.checked=false;accountabilityMessage='';update();app.querySelector('[data-da-action="'+t.action+'"]').focus();});
 app.querySelector('#da-check').onclick=()=>{accountabilityMessage=accountabilityCheck(q)?stage.feedback:'場面に示された担当と確認事項を見直しましょう。';update();app.querySelector('#da-check').focus();};
 app.querySelectorAll('[data-da-record-key]').forEach(b=>b.onclick=()=>{const key=b.dataset.daRecordKey,value=b.dataset.daRecordValue;q.record[key]=value;q.record.checked=false;accountabilityRecordMessage='';update();app.querySelector('[data-da-record-key="'+key+'"][data-da-record-value="'+value+'"]').focus();});
 app.querySelector('#da-record-check').onclick=()=>{const issues=accountabilityRecordCheck(q);accountabilityRecordMessage=issues.length?'次を見直しましょう：'+issues.map(k=>accountabilityRecordOptions[k].name).join('、')+'。':'この架空の受付の目的・項目・見直しがそろいました。';update();app.querySelector('#da-record-check').focus();};
 app.querySelectorAll('[data-da-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.daReflection;update();app.querySelector('[data-da-reflection="'+q.reflection+'"]').focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let recursionQuest,recursionMessage='';
function renderLeftRecursion(){
 const q=recursionQuest,t=q.trials[q.mode][q.target],g=recursionGrammars[q.mode],word=recursionReplay(q.mode,t.history),done=recursionDone(q);
 const modes=Object.entries(recursionGrammars).map(([k,v])=>'<button data-lr-mode="'+k+'" aria-pressed="'+(q.mode===k)+'">'+v.name+'</button>').join('');
 const targets=Object.entries(recursionTargets).map(([k,v])=>'<button data-lr-target="'+k+'" aria-pressed="'+(q.target===k)+'">'+v.name+(q.trials[q.mode][k].checked?' ✓':'')+'</button>').join('');
 const rules=Object.entries(g.rules).map(([k,v])=>'<button data-lr-rule="'+k+'">'+v+'</button>').join('');
 const showTree=node=>'<li>'+node.symbol+(node.children.length?'<ul style="padding-left:1.2em">'+node.children.map(showTree).join('')+'</ul>':'')+'</li>';
 const comparison=Object.keys(recursionGrammars).map(mode=>{const trial=q.trials[mode][q.target];return '<h3>'+recursionGrammars[mode].name+'</h3>'+(trial.checked?'<ul>'+showTree(recursionTree(mode,trial.history))+'</ul>':'<p>この規則で呪文を作って確かめると、木を表示します。</p>');}).join('');
 app.innerHTML='<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST '+active.number+' ／ '+active.tag+'</div><h1>'+active.title+'</h1><p>'+active.story+'</p></div></div><section class="panel"><h2>規則の札で呪文を作る</h2>'+draftMessage()+'<p>依頼309のように規則で記号を置き換えます。E と R はこれから展開する記号、a と + は完成する文字です。「空」は何も残さないことを表します。各規則で３つの呪文を作って確かめましょう。</p><div class="scenario-selector" role="group" aria-label="規則を選ぶ">'+modes+'</div><div class="scenario-selector" role="group" aria-label="作る呪文">'+targets+'</div><p>現在の巻物：<strong>'+word.split('').join(' ')+'</strong></p><p>手順：'+(t.history.length?t.history.map(x=>g.rules[x]).join(' → '):'まだありません')+'</p><p>導出：'+recursionTrace(q.mode,t.history).map(w=>w.split('').join(' ')).join(' ⇒ ')+'</p><div class="scenario-selector" role="group" aria-label="使う規則">'+rules+'</div><button id="lr-reset">この呪文を最初から作る</button><button id="lr-check">呪文を確かめる</button><p role="status">'+recursionMessage+'</p><details><summary>手がかり</summary><p>もとの規則では、先に E → E + a を繰り返してから E → a を使います。変換後は E → a R から始め、必要なだけ R → + a R を使って R → 空 で終えます。</p></details></section><section class="panel"><h2>構文木を比べる</h2><p>選んだ呪文をそれぞれの規則で作り、確かめると木を並べて見られます。上から規則を適用し、葉の a と + を左から読むと呪文になります。ε は空です。</p>'+comparison+'</section><section class="panel"><h2>規則の変化を振り返る</h2><p>この二つの規則の関係は？</p><div class="scenario-selector" role="group" aria-label="文法変換の振り返り"><button data-lr-reflection="same-strings" aria-pressed="'+(q.reflection==='same-strings')+'">同じ文字列を作れるが、導出の形は変わる</button><button data-lr-reflection="same-tree" aria-pressed="'+(q.reflection==='same-tree')+'">変換しても規則と構文木は必ず同じ</button></div>'+(q.reflection==='same-tree'?'<p>規則の E と R の展開順を比べましょう。文字列が同じでも構文木は異なります。</p>':'')+'</section><section class="panel"><h2>解析の精霊を進める</h2><p>入力 a + a を先頭から読みます。単純な精霊は、もとの規則では E に出会うといつも E → E + a を先に選びます。変換後は E → a R を使い、R は次の入力が + なら R → + a R、入力の終わりなら R → 空 を選びます。先頭の記号から順に処理します。</p><div class="scenario-selector" role="group" aria-label="解析する規則"><button data-lr-parser="left" aria-pressed="'+(q.parser.mode==='left')+'">もとの規則</button><button data-lr-parser="right" aria-pressed="'+(q.parser.mode==='right')+'">変換した規則</button></div>'+(()=>{const x=parserTrace(q.parser.mode,q.parser.steps[q.parser.mode]);return '<p role="status">手順 '+q.parser.steps[q.parser.mode]+' / 6 ／ 操作：'+x.action+'<br>処理待ち：'+(x.stack||'なし')+' ／ 残り入力：'+(x.input||'なし')+(x.accepted?' ／ 受理':'')+'</p>';})()+'<button id="lr-parser-step" '+(q.parser.steps[q.parser.mode]===6?'disabled':'')+'>１手進める</button><button id="lr-parser-reset">この規則をやり直す</button><p>６手進めると、もとの規則はどうなる？</p><div role="group" aria-label="解析の振り返り"><button data-lr-parser-answer="repeat" aria-pressed="'+(q.parser.answer==='repeat')+'">入力を読まず E を繰り返す</button><button data-lr-parser-answer="finish" aria-pressed="'+(q.parser.answer==='finish')+'">入力をすべて読んで受理する</button><button data-lr-parser-answer="both" aria-pressed="'+(q.parser.answer==='both')+'">両方とも同じ手順で受理する</button></div><button id="lr-parser-check">解析を確かめる</button>'+(q.parser.checked?'<p role="status">'+(q.parser.answer==='repeat'&&q.parser.steps.left===6&&q.parser.steps.right===6?'その通り。もとの規則では入力を読まないまま E が先頭に戻り、変換後は入力を読んで受理しました。':'両方の規則を６手進め、処理待ちと残り入力を比べましょう。')+'</p>':'')+'<p>この実験は規則の選び方を固定した模型です。６手で打ち切って観察しており、すべての解析器が左再帰を扱えないという意味ではありません。</p></section><section class="panel"><h2>結合の違いを試す</h2><p>別の例として同じ 8 − 3 − 2 を、二つの木に分けて計算します。上の a と + の文法そのものの計算ではありません。どちらを先にまとめるか選び、両方の結果を比べましょう。</p><div class="scenario-selector" role="group" aria-label="結合の選択"><button data-lr-assoc="left" aria-pressed="'+(q.association.selected==='left')+'">左を先に</button><button data-lr-assoc="right" aria-pressed="'+(q.association.selected==='right')+'">右を先に</button></div><p role="status">'+(q.association.seen.includes(q.association.selected)?(q.association.selected==='left'?'(8 − 3) − 2 = 5 − 2 = 3':'8 − (3 − 2) = 8 − 1 = 7'):'「計算してみる」を押しましょう。')+'</p><button id="lr-assoc-run">計算してみる</button><p>試した結合：'+q.association.seen.length+' / 2</p><p>二つの計算結果は？</p><div role="group" aria-label="結合の比較"><button data-lr-assoc-answer="different" aria-pressed="'+(q.association.answer==='different')+'">異なる</button><button data-lr-assoc-answer="same" aria-pressed="'+(q.association.answer==='same')+'">同じ</button></div><button id="lr-assoc-check">比較を確かめる</button>'+(q.association.checked?'<p role="status">'+(q.association.seen.length===2&&q.association.answer==='different'?'その通り。左は３、右は７です。同じ文字列でも結合により計算結果が変わります。':'両方を計算し、結果を見比べましょう。')+'</p>':'')+'<p>変換後の文法でも、解析後に左結合の構文木を組み立てることで、もとの結合を保てます。文字列が同じことだけでは、その意味まで同じと保証できません。</p><p>参考：<a href="https://craftinginterpreters.com/parsing-expressions.html" target="_blank" rel="noopener noreferrer">Crafting Interpreters：結合と構文解析 ↗</a></p></section>'+(done?'<section class="result panel"><h2>二つの規則を比べました！</h2><p>もとの規則は E の先頭に再び E が現れる直接左再帰です。変換後は先に a を出し、R が + a を０回以上追加します。どちらも a に + a が０回以上続く文字列を作ります。</p><p>構文木や結合の扱いは変化し得ます。この依頼は一つの文法の例で、任意の文法変換や実際の解析器を評価しません。</p><button id="return">ギルドへ戻る</button></section>':'')+'<aside class="reference">学びの手がかり：<a href="https://web.stanford.edu/class/archive/cs/cs143/cs143.1156/handouts/parsing.pdf" target="_blank" rel="noopener noreferrer">Stanford：左再帰の除去 ↗</a></aside></div>';
 const update=()=>{writeDraft(active.id,q);if(recursionDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable&&q.association.selected==='left'&&!q.association.seen.length&&q.association.answer===null&&q.parser.mode==='left'&&q.parser.steps.left===0&&q.parser.steps.right===0&&q.parser.answer===null)clearDraft(active.id);}renderLeftRecursion();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);recursionQuest=recursionCreate();recursionMessage='';renderLeftRecursion();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-lr-mode]').forEach(b=>b.onclick=()=>{q.mode=b.dataset.lrMode;recursionMessage='';update();app.querySelector('[data-lr-mode="'+q.mode+'"]').focus();});
 app.querySelectorAll('[data-lr-target]').forEach(b=>b.onclick=()=>{q.target=b.dataset.lrTarget;recursionMessage='';update();app.querySelector('[data-lr-target="'+q.target+'"]').focus();});
 app.querySelectorAll('[data-lr-rule]').forEach(b=>b.onclick=()=>{const action=b.dataset.lrRule;try{recursionAct(q,action);recursionMessage='規則を使いました。';}catch(e){recursionMessage=e.message;}update();app.querySelector('[data-lr-rule="'+action+'"]').focus();});
 app.querySelector('#lr-reset').onclick=()=>{t.history=[];t.checked=false;recursionMessage='この呪文を最初から作ります。';update();app.querySelector('#lr-reset').focus();};
 app.querySelector('#lr-check').onclick=()=>{recursionMessage=recursionCheck(q)?'依頼の呪文ができました。':'作る呪文と、残っている E・R を確かめましょう。';update();app.querySelector('#lr-check').focus();};
 app.querySelectorAll('[data-lr-parser]').forEach(b=>b.onclick=()=>{q.parser.mode=b.dataset.lrParser;q.parser.checked=false;update();app.querySelector('[data-lr-parser="'+q.parser.mode+'"]').focus();});
 app.querySelector('#lr-parser-step').onclick=()=>{const m=q.parser.mode;if(q.parser.steps[m]<6)q.parser.steps[m]++;q.parser.checked=false;update();(app.querySelector('#lr-parser-step:enabled')||app.querySelector('[data-lr-parser="'+m+'"]')).focus();};
 app.querySelector('#lr-parser-reset').onclick=()=>{q.parser.steps[q.parser.mode]=0;q.parser.checked=false;update();app.querySelector('#lr-parser-reset').focus();};
 app.querySelectorAll('[data-lr-parser-answer]').forEach(b=>b.onclick=()=>{q.parser.answer=b.dataset.lrParserAnswer;q.parser.checked=false;update();app.querySelector('[data-lr-parser-answer="'+q.parser.answer+'"]').focus();});
 app.querySelector('#lr-parser-check').onclick=()=>{if(q.parser.answer===null){app.querySelector('#lr-parser-check').textContent='先に答えを選びましょう';return;}q.parser.checked=true;update();app.querySelector('#lr-parser-check').focus();};
 app.querySelectorAll('[data-lr-assoc]').forEach(b=>b.onclick=()=>{q.association.selected=b.dataset.lrAssoc;q.association.checked=false;update();app.querySelector('[data-lr-assoc="'+q.association.selected+'"]').focus();});
 app.querySelector('#lr-assoc-run').onclick=()=>{if(!q.association.seen.includes(q.association.selected))q.association.seen.push(q.association.selected);q.association.checked=false;update();app.querySelector('#lr-assoc-run').focus();};
 app.querySelectorAll('[data-lr-assoc-answer]').forEach(b=>b.onclick=()=>{q.association.answer=b.dataset.lrAssocAnswer;q.association.checked=false;update();app.querySelector('[data-lr-assoc-answer="'+q.association.answer+'"]').focus();});
 app.querySelector('#lr-assoc-check').onclick=()=>{if(q.association.answer===null){app.querySelector('#lr-assoc-check').textContent='先に答えを選びましょう';return;}q.association.checked=true;update();app.querySelector('#lr-assoc-check').focus();};
 app.querySelectorAll('[data-lr-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.lrReflection;update();app.querySelector('[data-lr-reflection="'+q.reflection+'"]').focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let gestureQuest,gestureMessage='',gestureCompareMessage='';
function renderGestureMap(){
 const q=gestureQuest,done=gestureDone(q),comparison=q.comparison,trial=comparison.trials[comparison.selected];
 const places=gesturePlaces.map((name,i)=>'<li>'+(i===q.position?'📍 ':'')+name+(q.visited[i]?' ✓':'')+'</li>').join('');
 app.innerHTML='<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST '+active.number+' ／ '+active.tag+'</div><h1>'+active.title+'</h1><p>'+active.story+'</p></div></div><section class="panel"><h2>三つの場所へ出かける</h2>'+draftMessage()+'<p>依頼1297の操作一覧に続き、地図を動かす方法を試します。地図を指やマウスで左右になぞるか、ボタンを押して三つの場所を訪れましょう。ボタンは Tab と Enter でも使えます。</p><div id="gm-surface" style="touch-action:pan-y pinch-zoom; border:2px solid currentColor; border-radius:.6rem; padding:1rem; min-height:5rem" aria-label="地図。左右のボタンでも移動できます"><strong>地図：'+gesturePlaces[q.position]+'</strong><p>ここを左右になぞると地図をめくれます。現在の判定距離：'+comparison.selected+' CSS ピクセル。</p></div><div class="scenario-selector" role="group" aria-label="地図の移動"><button data-gm-move="-1">← 西へ</button><button data-gm-move="1">東へ →</button></div><p id="gm-status" role="status">'+gestureMessage+'</p><ul>'+places+'</ul><details><summary>地図が動く条件</summary><p>この地図は、押した位置から離した位置までの横の移動が選択した判定距離以上で、縦より大きいときに一つめくれます。途中で操作が取り消されたときは移動しません。縦のスクロールとピンチによる拡大はブラウザが扱えます。</p></details></section><section class="panel"><h2>二つの工房の判定を比べる</h2><p>別の地図では、なぞった長さを何ピクセルから移動と見なすかが違います。左へ60 CSS ピクセル、縦には動かさない同じ操作を行ったとき、それぞれの地図が動くか予想し、試しましょう。選んだ判定距離は上の地図にも適用されます。初期設定は40です。</p><div class="scenario-selector" role="group" aria-label="判定距離"><button data-gm-threshold="40" aria-pressed="'+(comparison.selected==='40')+'">40ピクセル以上'+(comparison.trials['40'].checked?' ✓':'')+'</button><button data-gm-threshold="80" aria-pressed="'+(comparison.selected==='80')+'">80ピクセル以上'+(comparison.trials['80'].checked?' ✓':'')+'</button></div><div class="scenario-selector" role="group" aria-label="結果の予想"><button data-gm-guess="yes" aria-pressed="'+(trial.guess===true)+'">地図が動く</button><button data-gm-guess="no" aria-pressed="'+(trial.guess===false)+'">地図は動かない</button></div><button id="gm-compare">同じ操作を試す</button><p id="gm-compare-status" role="status">'+gestureCompareMessage+'</p><p>これは二つの仮想的な判定設定の比較です。実際の端末間やアプリ間の一貫性を検査したものではありません。</p><h3>動きの方向も試す</h3><p>設定した距離のまま、横と縦の移動量が異なる３つの動きを試せます。横方向が縦より大きい場合だけ、地図の横移動と判定します。</p><div class="scenario-selector" role="group" aria-label="試す移動量">'+Object.entries(gestureProbes).map(([k,v])=>'<button data-gm-probe="'+k+'">'+v.name+'</button>').join('')+'</div><p id="gm-probe-status" role="status"></p></section><section class="panel"><h2>旅人の操作を振り返る</h2><p>左右になぞることが難しい旅人にも同じ地図を使ってもらうには？</p><div class="scenario-selector" role="group" aria-label="代替操作"><button data-gm-reflection="alternative" aria-pressed="'+(q.reflection==='alternative')+'">同じ移動ができるボタンを用意する</button><button data-gm-reflection="gesture" aria-pressed="'+(q.reflection==='gesture')+'">なぞる速さだけを上げる</button></div>'+(q.reflection==='gesture'?'<p>速く動かす方法だけでは、なぞる操作自体が難しい人の代わりになりません。</p>':'')+'</section>'+(done?'<section class="result panel"><h2>三つの場所を訪ねました！</h2><p>左右になぞる操作とボタンは、どちらも同じ三つの場所へ移れます。使いやすさは人や機器によって異なるため、実際の利用者や機器でも確かめましょう。</p><p>これは一つの地図と簡単な判定の例です。すべてのタッチ機器、複数指の操作や規格適合を検証するものではありません。</p><button id="return">ギルドへ戻る</button></section>':'')+'<aside class="reference">学びの手がかり：<a href="https://www.w3.org/WAI/WCAG22/Understanding/pointer-gestures.html" target="_blank" rel="noopener noreferrer">W3C：ポインタージェスチャー ↗</a> ／ <a href="https://developer.mozilla.org/en-US/docs/Web/API/Pointer_events" target="_blank" rel="noopener noreferrer">MDN：ポインターイベント ↗</a></aside></div>';
 const update=()=>{writeDraft(active.id,q);if(gestureDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderGestureMap();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);gestureQuest=gestureCreate();gestureMessage='';gestureCompareMessage='';renderGestureMap();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-gm-move]').forEach(b=>b.onclick=()=>{const d=Number(b.dataset.gmMove),previous=q.position;gestureMove(q,d);gestureMessage=previous===q.position?'地図の端です。':gesturePlaces[q.position]+'へ移動しました。';update();app.querySelector('[data-gm-move="'+d+'"]').focus();});
 app.querySelectorAll('[data-gm-threshold]').forEach(b=>b.onclick=()=>{comparison.selected=b.dataset.gmThreshold;gestureCompareMessage='';update();app.querySelector('[data-gm-threshold="'+comparison.selected+'"]').focus();});
 app.querySelectorAll('[data-gm-guess]').forEach(b=>b.onclick=()=>{trial.guess=b.dataset.gmGuess==='yes';trial.checked=false;gestureCompareMessage='';update();app.querySelector('[data-gm-guess="'+b.dataset.gmGuess+'"]').focus();});
 app.querySelector('#gm-compare').onclick=()=>{try{const result=gestureCompareCheck(q);gestureCompareMessage=(result.moved?'地図が動きました。':'地図は動きませんでした。')+(result.correct?'予想が合いました。':'判定距離と60を比べましょう。');}catch(e){gestureCompareMessage=e.message;}update();app.querySelector('#gm-compare').focus();};
 app.querySelectorAll('[data-gm-probe]').forEach(b=>b.onclick=()=>{const probe=gestureProbes[b.dataset.gmProbe],d=gestureDirection(probe.dx,probe.dy,Number(comparison.selected));app.querySelector('#gm-probe-status').textContent=d?'横への移動と判定します。':'横への移動とは判定しません。';});
 app.querySelectorAll('[data-gm-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.gmReflection;update();app.querySelector('[data-gm-reflection="'+q.reflection+'"]').focus();});
 const surface=app.querySelector('#gm-surface');let start=null;
 surface.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0||start)return;start={id:e.pointerId,x:e.clientX,y:e.clientY};surface.setPointerCapture(e.pointerId);});
 surface.addEventListener('pointercancel',e=>{if(start?.id===e.pointerId){start=null;gestureMessage='操作が取り消され、地図は動きませんでした。';app.querySelector('#gm-status').textContent=gestureMessage;}});
 surface.addEventListener('pointerup',e=>{if(!start||start.id!==e.pointerId)return;const d=gestureDirection(e.clientX-start.x,e.clientY-start.y,Number(comparison.selected));start=null;if(d){const previous=q.position;gestureMove(q,d);gestureMessage=previous===q.position?'地図の端です。':gesturePlaces[q.position]+'へ移動しました。';update();}else{gestureMessage='横の移動が短いか、縦の移動の方が大きいため地図は動きませんでした。';app.querySelector('#gm-status').textContent=gestureMessage;}});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let interfaceQuest,interfaceMessage='';
function renderInterfaceWorkshop(){
 const q=interfaceQuest,c=interfaceCases[q.selected],done=interfaceDone(q),seen=q.seen[q.selected];
 const cases=Object.entries(interfaceCases).map(([k,v])=>'<button data-iw-case="'+k+'" aria-pressed="'+(q.selected===k)+'">'+v.name+(q.seen[k].weak&&q.seen[k].improved?' ✓':'')+'</button>').join('');
 const variants=Object.entries(interfaceVariants).map(([k,v])=>'<button data-iw-variant="'+k+'" aria-pressed="'+(q.variant===k)+'">'+v+(seen[k]?' ✓':'')+'</button>').join('');
 const choices=Object.entries(c.choices).map(([k,v])=>'<button data-iw-answer="'+k+'" aria-pressed="'+(q.answers[q.selected]===k)+'">'+v+'</button>').join('');
 const diagrams={window:'荷物の札 → 確認の窓 → 閉じる → '+(q.variant==='weak'?'別の場所':'荷物の札'),icon:q.variant==='weak'?'▣':'▣ 荷物を保存',menu:q.variant==='weak'?'道具箱 → ポインターで開く':'道具箱 → キーボードでも開く・選ぶ・閉じる'};
 app.innerHTML='<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST '+active.number+' ／ '+active.tag+'</div><h1>'+active.title+'</h1><p>'+active.story+'</p></div></div><section class="panel"><h2>道具箱を試す</h2>'+draftMessage()+'<p>依頼351で方向ボタンと矢印キーを試したように、今度は操作の見せ方と操作後の行き先を調べます。３つの場所で二つの案を試して、旅人に起きることを比べましょう。</p><div class="scenario-selector" role="group" aria-label="調べる場所">'+cases+'</div><div class="scenario-selector" role="group" aria-label="工房の案">'+variants+'</div><p><strong>選んだ案：</strong> '+diagrams[q.selected]+'</p><button id="iw-observe">旅人と試す</button><p role="status">'+interfaceMessage+'</p><h3>'+c.question+'</h3><div class="scenario-selector" role="group" aria-label="気づいたこと">'+choices+'</div>'+(q.answers[q.selected]&&q.answers[q.selected]!==c.expected?'<p>二つの案を試して、旅人が次の操作を続けられるか考えましょう。</p>':'')+'<details><summary>手がかり</summary><p>場所、札の意味、入力方法をそれぞれ確かめます。絵は人によって同じ意味に見えるとは限りません。</p></details></section><section class="panel"><h2>実際に道具を開いてみる</h2><p>キーボードでは Tab で札を移り、Enter または Space で開けます。確認の窓では Escape でも閉じられます。閉じた後、どの札に戻るか確かめましょう。</p><button id="iw-dialog-open">荷物の確認を開く</button><dialog id="iw-dialog" aria-labelledby="iw-dialog-title"><h3 id="iw-dialog-title">荷物の確認</h3><p>薬草を道具箱に入れますか？ この練習では実際の荷物は変わりません。</p><button id="iw-dialog-close" autofocus>確認して閉じる</button><button id="iw-dialog-cancel">取り消して閉じる</button></dialog><details id="iw-disclosure"><summary>道具箱の操作一覧</summary><p>これは開閉式の一覧です。Tab で項目へ移り、Enter または Space で選べます。</p><button id="iw-list-save">▣ 荷物を保存</button><button id="iw-list-show">☷ 荷物を見る</button></details><p id="iw-live-message" role="status"></p><p>この操作一覧は HTML の開閉式の一覧です。矢印キーで項目を移動するアプリ型メニューとは操作方法が異なります。</p></section><section class="panel"><h2>旅人への届け方を振り返る</h2><p>この模型で良さそうな案を見つけたら、次に何をするとよいでしょう？</p><div class="scenario-selector" role="group" aria-label="振り返り"><button data-iw-reflection="test" aria-pressed="'+(q.reflection==='test')+'">実際の利用者や支援技術でも確かめる</button><button data-iw-reflection="assume" aria-pressed="'+(q.reflection==='assume')+'">この模型だけで誰でも使えると決める</button></div>'+(q.reflection==='assume'?'<p>旅人によって入力方法や必要な支援が異なります。模型だけでは分かりません。</p>':'')+'</section>'+(done?'<section class="result panel"><h2>道具箱の案を比べました！</h2><p>窓を閉じた後の行き先、アイコンの意味、メニューの操作方法を別々に考えました。この依頼は固定の例であり、実際の実装や支援技術による評価、規格への適合を証明しません。</p><button id="return">ギルドへ戻る</button></section>':'')+'<aside class="reference">学びの手がかり：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/menu-button/" target="_blank" rel="noopener noreferrer">W3C：メニューボタン ↗</a> ／ <a href="https://www.w3.org/WAI/WCAG22/Techniques/html/H102" target="_blank" rel="noopener noreferrer">W3C：確認の窓 ↗</a></aside></div>';
 const update=()=>{writeDraft(active.id,q);if(interfaceDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderInterfaceWorkshop();};
 app.querySelector('#back').onclick=renderHome;
 const dialog=app.querySelector('#iw-dialog'),liveMessage=app.querySelector('#iw-live-message');
 app.querySelector('#iw-dialog-open').onclick=()=>dialog.showModal();
 app.querySelector('#iw-dialog-close').onclick=()=>dialog.close();
 app.querySelector('#iw-dialog-cancel').onclick=()=>dialog.close();
 dialog.onclose=()=>{liveMessage.textContent='確認の窓を閉じました。';};
 app.querySelector('#iw-list-save').onclick=()=>{app.querySelector('#iw-live-message').textContent='荷物を保存する札を選びました（練習）。';};
 app.querySelector('#iw-list-show').onclick=()=>{app.querySelector('#iw-live-message').textContent='荷物を見る札を選びました（練習）。';};
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);interfaceQuest=interfaceCreate();interfaceMessage='';renderInterfaceWorkshop();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-iw-case]').forEach(b=>b.onclick=()=>{q.selected=b.dataset.iwCase;interfaceMessage='';update();app.querySelector('[data-iw-case="'+q.selected+'"]').focus();});
 app.querySelectorAll('[data-iw-variant]').forEach(b=>b.onclick=()=>{q.variant=b.dataset.iwVariant;interfaceMessage='';update();app.querySelector('[data-iw-variant="'+q.variant+'"]').focus();});
 app.querySelector('#iw-observe').onclick=()=>{interfaceMessage=interfaceObserve(q);update();app.querySelector('#iw-observe').focus();};
 app.querySelectorAll('[data-iw-answer]').forEach(b=>b.onclick=()=>{q.answers[q.selected]=b.dataset.iwAnswer;update();app.querySelector('[data-iw-answer="'+q.answers[q.selected]+'"]').focus();});
 app.querySelectorAll('[data-iw-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.iwReflection;update();app.querySelector('[data-iw-reflection="'+q.reflection+'"]').focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let hazardScheduleQuest,hazardScheduleMessage='';
function renderHazardSchedule(){
 const q=hazardScheduleQuest,s=hazardScheduleReplay(q.mode,q.history),done=hazardScheduleDone(q);
 const stages={start:'まだ先頭を見ていない',read:'先頭を覚えた',published:'目印を出した',valid:'再確認に成功',stale:'再確認に失敗',used:'札を読んだ',done:'作業を終えた'};
 const modes=Object.entries(hazardScheduleModes).map(([k,v])=>'<button data-hs-mode="'+k+'" aria-pressed="'+(q.mode===k)+'">'+v+'</button>').join('');
 const actions=Object.entries(hazardScheduleActions).map(([k,v])=>'<button data-hs-action="'+k+'">'+v+'</button>').join('');
 const goals=[['unsafe','目印なしで、回収後に読みを試す'],['protected','目印で回収を延期し、読み終えてから回収する'],['late','回収後の公表に気づき、古い参照を捨てる']].map(([k,v])=>'<li>'+(q.seen[k]?'✓ ':'□ ')+v+'</li>').join('');
 app.innerHTML='<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST '+active.number+' ／ '+active.tag+'</div><h1>'+active.title+'</h1><p>'+active.story+'</p></div></div><section class="panel"><h2>二人の精霊を動かす</h2>'+draftMessage()+'<p>依頼816の回収延期を、今度は自分で順番を決めて試します。読み手が先頭の札 A を覚えた後、読み手と回収係の操作を一つずつ選べます。３つの結果に到達したら、それぞれ記録しましょう。</p><ul>'+goals+'</ul><div class="scenario-selector" role="group" aria-label="試す方法">'+modes+'</div><p>方法の切り替えや試行のやり直しでは操作順が初期化されます。記録済みの結果は残ります。</p><button id="hs-reset">この試行をやり直す</button><p><strong>読み手：</strong>'+stages[s.reader]+' ／ <strong>先頭：</strong>'+(s.head==='A'?'札 A':'空')+' ／ <strong>目印：</strong>'+(s.hazard?'あり':'なし')+'</p><p><strong>札 A：</strong>'+(s.freed?'回収済み':s.retired?'先頭から外された':'先頭にある')+' ／ <strong>回収の延期：</strong>'+(s.deferred?'経験あり':'まだない')+'</p><p>操作：'+(q.history.length?q.history.map(k=>hazardScheduleActions[k]).join(' → '):'まだありません')+'</p><div class="scenario-selector" role="group" aria-label="精霊の操作">'+actions+'</div><button id="hs-record">この結果を記録する</button><p role="status">'+(hazardScheduleMessage||s.message)+'</p><details><summary>手がかり</summary><p>目印なしでは、先頭を覚えた後に回収される順番を試します。目印ありでは、再確認の前後に回収係が動く二つの順番を比べます。目印が変わると、回収係はもう一度調べられます。</p></details><p>この模型では各操作が一度に起こり、全員に同じ順序で見えます。札は一枚で、回収後に同じ場所へ新しい札は置きません。危険な読みは実行せず、回収済みだったと表示します。</p></section><section class="panel"><h2>目印を出した後の再確認</h2><p>回収係が目印を見る前に札を回収したかもしれません。目印を出した後、読む前に何を確かめますか？</p><div class="scenario-selector" role="group" aria-label="再確認の振り返り"><button data-hs-reflection="recheck" aria-pressed="'+(q.reflection==='recheck')+'">先頭が覚えた札のままか再確認する</button><button data-hs-reflection="publish" aria-pressed="'+(q.reflection==='publish')+'">目印を出せば、過去に回収されていても読める</button></div>'+(q.reflection==='publish'?'<p>目印は過去の回収を取り消せません。先頭が変わっていたら参照を捨てます。</p>':'')+'</section>'+(done?'<section class="result panel"><h2>三つの順番を確かめました！</h2><p>目印の公表後に先頭を再確認することで、既に外された札を読まずに捨てられます。回収係が目印を見た場合は回収を延期し、目印が消えてから再び調べます。</p><p>これは限定された順序モデルです。実際のメモリ順序、再利用や ABA、実装全体の安全性・進行性の証明は扱いません。</p><button id="return">ギルドへ戻る</button></section>':'')+'<aside class="reference">学びの手がかり：<a href="https://research.ibm.com/publications/hazard-pointers-safe-memory-reclamation-for-lock-free-objects" target="_blank" rel="noopener noreferrer">IBM Research：Hazard pointers ↗</a></aside></div>';
 const update=()=>{writeDraft(active.id,q);if(hazardScheduleDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderHazardSchedule();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);hazardScheduleQuest=hazardScheduleCreate();hazardScheduleMessage='';renderHazardSchedule();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-hs-mode]').forEach(b=>b.onclick=()=>{q.mode=b.dataset.hsMode;q.history=[];hazardScheduleMessage='方法を選びました。';update();app.querySelector('[data-hs-mode="'+q.mode+'"]').focus();});
 app.querySelector('#hs-reset').onclick=()=>{q.history=[];hazardScheduleMessage='この試行を最初からやり直します。';update();app.querySelector('#hs-reset').focus();};
 app.querySelectorAll('[data-hs-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.hsAction;try{hazardScheduleMessage=hazardScheduleAct(q,action).message;}catch(e){hazardScheduleMessage=e.message;}update();app.querySelector('[data-hs-action="'+action+'"]').focus();});
 app.querySelector('#hs-record').onclick=()=>{try{hazardScheduleRecord(q);hazardScheduleMessage='この結果を記録しました。';}catch(e){hazardScheduleMessage=e.message;}update();app.querySelector('#hs-record').focus();};
 app.querySelectorAll('[data-hs-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.hsReflection;update();app.querySelector('[data-hs-reflection="'+q.reflection+'"]').focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let exampleQueryQuest,exampleQueryMessage='';
function renderExampleQuery(){
 const q=exampleQueryQuest,t=q.trials[q.selected],task=exampleTasks[q.selected],done=exampleQueryDone(q),villageName=v=>v==='east'?'東の村':'西の村',result=t.ran?exampleQuery(t.village,t.minimum,t.output,t.day):[];
 const tasks=Object.entries(exampleTasks).map(([k,v])=>'<button data-eq-task="'+k+'" aria-pressed="'+(q.selected===k)+'">'+v.name+(q.trials[k].checked?' ✓':'')+'</button>').join('');
 const rows=exampleDays[t.day].rows.map(r=>'<tr><td>'+r.person+'</td><td>'+villageName(r.village)+'</td><td>'+r.count+'</td></tr>').join('');
 const days=Object.entries(exampleDays).map(([k,v])=>'<button data-eq-day="'+k+'" aria-pressed="'+(t.day===k)+'">'+v.name+'</button>').join('');
 const controls=[['village','村の条件',exampleVillages],['minimum','束数の条件',exampleMinimums],['output','返す項目',exampleOutputs]].map(([key,label,options])=>'<h3>'+label+'</h3><div class="scenario-selector" role="group" aria-label="'+label+'">'+Object.entries(options).map(([k,v])=>'<button data-eq-key="'+key+'" data-eq-value="'+k+'" aria-pressed="'+(t[key]===k)+'">'+v+'</button>').join('')+'</div>').join('');
 app.innerHTML='<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST '+active.number+' ／ '+active.tag+'</div><h1>'+active.title+'</h1><p>'+active.story+'</p></div></div><section class="panel"><h2>薬草台帳の問い合わせ</h2>'+draftMessage()+'<p>依頼462の配達台帳と同じように村ごとの記録を調べます。札で条件と返す項目を組み合わせ、試してから薬師へ届けましょう。</p><div class="scenario-selector" role="group" aria-label="依頼を選ぶ">'+tasks+'</div><p><strong>依頼：</strong>'+task.goal+'</p><p>同じ条件を二つの日の台帳で試せます。別の日には西の村へ１束の配達が増えています。</p><div class="scenario-selector" role="group" aria-label="台帳の日">'+days+'</div><div class="truth-wrap"><table class="truth-table"><caption>配達台帳</caption><thead><tr><th scope="col">名前</th><th scope="col">村</th><th scope="col">束数</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+controls+'<button id="eq-run">条件を試す</button><button id="eq-check">依頼を確かめる</button><p role="status">'+exampleQueryMessage+'</p>'+(t.ran?'<p>結果：'+(result.length?result.map(x=>t.output==='village'?villageName(x):x).join('、'):'該当なし')+'</p>':'')+'<p>村を返すときは、条件に合う配達が少なくとも１件ある村を１回ずつ表示します。同じ結果が偶然得られても、違う条件は別の台帳で異なる結果になる場合があります。</p><details><summary>手がかり</summary><p>村・束数・返す項目を、それぞれ依頼の文章と照らしましょう。０束以上は４行すべてに当てはまります。</p></details></section><section class="panel"><h2>村の条件を振り返る</h2><p>「４束以上の配達がある村」の意味は？</p><div class="scenario-selector" role="group" aria-label="存在条件"><button data-eq-reflection="exists" aria-pressed="'+(q.reflection==='exists')+'">その村への配達のうち、４束以上が少なくとも１件ある</button><button data-eq-reflection="all" aria-pressed="'+(q.reflection==='all')+'">その村への配達がすべて４束以上である</button></div>'+(q.reflection==='all'?'<p>西の村には４束と２束の配達があります。１件あることと、すべてが条件に合うことを比べましょう。</p>':'')+'</section>'+(done?'<section class="result panel"><h2>三つの依頼を届けました！</h2><p>村と束数の条件を同時に満たす行を選び、必要な項目を返しました。村に条件を満たす配達が少なくとも１件あるかという考え方は、存在条件の一例です。</p><p>これは QBE を参考にした固定の札と有限の台帳です。一般の関係論理、QBE の全機能、実際の問い合わせ言語や DB 操作は評価しません。</p><button id="return">ギルドへ戻る</button></section>':'')+'<aside class="reference">学びの手がかり：<a href="https://public.dhe.ibm.com/software/data/qmf/xhtml/QMFusing/dsqk2mst11.htm" target="_blank" rel="noopener noreferrer">IBM：例による問い合わせ ↗</a> ／ <a href="https://www.cs.cornell.edu/~ross/publications/proofgen/proofgen_tate_popl10_tr.pdf" target="_blank" rel="noopener noreferrer">Cornell：存在条件の問い合わせ ↗</a></aside></div>';
 const update=()=>{writeDraft(active.id,q);if(exampleQueryDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderExampleQuery();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);exampleQueryQuest=exampleQueryCreate();exampleQueryMessage='';renderExampleQuery();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-eq-task]').forEach(b=>b.onclick=()=>{q.selected=b.dataset.eqTask;exampleQueryMessage='';update();app.querySelector('[data-eq-task="'+q.selected+'"]').focus();});
 app.querySelectorAll('[data-eq-day]').forEach(b=>b.onclick=()=>{t.day=b.dataset.eqDay;exampleQueryMessage=t.ran?'同じ条件を選んだ日の台帳に当てはめました。':'台帳の日を選びました。';update();app.querySelector('[data-eq-day="'+t.day+'"]').focus();});
 app.querySelectorAll('[data-eq-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.eqKey,v=b.dataset.eqValue;t[k]=v;t.ran=false;t.checked=false;exampleQueryMessage='条件を選びました。';update();app.querySelector('[data-eq-key="'+k+'"][data-eq-value="'+v+'"]').focus();});
 app.querySelector('#eq-run').onclick=()=>{t.ran=true;t.checked=false;exampleQueryMessage='台帳に条件を当てはめました。';update();app.querySelector('#eq-run').focus();};
 app.querySelector('#eq-check').onclick=()=>{try{exampleQueryMessage=exampleQueryCheck(q)?'依頼の条件と返す項目が一致しました。':'依頼の村・束数・返す項目を見直しましょう。';}catch(e){exampleQueryMessage=e.message;}update();app.querySelector('#eq-check').focus();};
 app.querySelectorAll('[data-eq-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.eqReflection;update();app.querySelector('[data-eq-reflection="'+q.reflection+'"]').focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let analogyQuest,analogyMessage='';
function renderEthicalAnalogy(){
 const q=analogyQuest,c=analogyCases[q.selected],t=q.trials[q.selected],done=analogyDone(q);
 const groups=[['similar','判断に関係する共通点'],['difference','追加で確かめるべき違い'],['conclusion','この例からの慎重な考え方']];
 app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div></div><section class="panel"><h2>以前の出来事と新しい計画</h2>${draftMessage()}<p>依頼1209の掲示板について考えたように、関わる人への影響を確かめます。以前の例は、似た新しい場面で何を尋ねるかの手がかりになります。</p><div class="scenario-selector" role="group" aria-label="比較する出来事">${Object.entries(analogyCases).map(([k,v])=>`<button data-ea-case="${k}" aria-pressed="${q.selected===k}">${v.name}${q.trials[k].checked?' ✓':''}</button>`).join('')}</div><p>${c.prior}</p><p>${c.current}</p>${groups.map(([key,label])=>`<h3>${label}</h3><div class="scenario-selector" role="group" aria-label="${label}">${(key==='difference'?[false,true]:[true,false]).map(value=>`<button data-ea-key="${key}" data-ea-value="${value?'yes':'no'}" aria-pressed="${t[key]===value}">${value?c[key]:c.decoys[key]}</button>`).join('')}</div>`).join('')}<button id="ea-check">組み立てた考えを確かめる</button><p role="status">${analogyMessage}</p>${t.checked?`<p>${c.explanation}</p>`:''}<details><summary>手がかり</summary><p>共通点が何を考えるきっかけになるかを見て、今回まだ知らないことと区別しましょう。</p></details></section><section class="panel"><h2>類推の使い方を振り返る</h2><p>両方の比較を確かめ、例からどこまで言えるかを選びましょう。</p><div class="scenario-selector" role="group" aria-label="類推の限界"><button data-ea-reflection="limits" aria-pressed="${q.reflection==='limits'}">似た点は手がかりになるが、違いや関係者の状況も調べる</button><button data-ea-reflection="certain" aria-pressed="${q.reflection==='certain'}">似た点が一つあれば、判断は必ず同じになる</button></div></section>${done?'<section class="result panel"><h2>二つの例を比べました！</h2><p>以前の例は、名前の公開や案内の利用に関する懸念を見つける手がかりになります。新しい場面では公開範囲、支援の有無、当事者の希望なども確認します。</p><p>これは架空の２例です。実際の関係者の調査や法的判断、自由な文章による議論は評価しません。</p><button id="return">ギルドへ戻る</button></section>':''}<aside class="reference">学びの手がかり：<a href="https://plato.stanford.edu/entries/reasoning-analogy/" target="_blank" rel="noopener noreferrer">Stanford Encyclopedia：類推による推論 ↗</a> ／ <a href="https://www.acm.org/code-of-ethics" target="_blank" rel="noopener noreferrer">ACM：倫理規範 ↗</a></aside></div>`;
 const update=()=>{writeDraft(active.id,q);if(analogyDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderEthicalAnalogy();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);analogyQuest=analogyCreate();analogyMessage='';renderEthicalAnalogy();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-ea-case]').forEach(b=>b.onclick=()=>{q.selected=b.dataset.eaCase;analogyMessage='';update();app.querySelector(`[data-ea-case="${q.selected}"]`).focus();});
 app.querySelectorAll('[data-ea-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.eaKey,v=b.dataset.eaValue;t[k]=v==='yes';t.checked=false;analogyMessage='';update();app.querySelector(`[data-ea-key="${k}"][data-ea-value="${v}"]`).focus();});
 app.querySelector('#ea-check').onclick=()=>{analogyCheck(q);analogyMessage=analogyFeedback(q);update();app.querySelector('#ea-check').focus();};
 app.querySelectorAll('[data-ea-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.eaReflection;analogyMessage=q.reflection==='limits'?'類推を手がかりに、今回の事情を確かめます。':'似た点だけでは判断は確定しません。';update();app.querySelector(`[data-ea-reflection="${q.reflection}"]`).focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
let procedureQuest,procedureMessage='';
function renderStoredProcedure(){
 const q=procedureQuest,t=q.trials[`${q.role}:${q.amount}`],done=procedureDone(q);
 app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div></div><section class="panel"><h2>薬草庫に手続きを呼び出す</h2>${draftMessage()}<p>台帳側には「頼まれた束数が在庫以下なら届け、在庫を減らす。足りなければ何もしない」という手続きが保存されています。この模型では呼出し権限を持つ薬師だけが使えます。各試行は在庫５束から始めます。</p><p>呼び出す人と渡す数を選び、結果を予想して試しましょう。依頼1073で試した条件付き更新のように、条件によって台帳の変化が異なります。</p><div class="scenario-selector" role="group" aria-label="呼び出す人">${Object.entries(procedureRoles).map(([k,v])=>`<button data-sp-role="${k}" aria-pressed="${q.role===k}">${v}</button>`).join('')}</div><div class="scenario-selector" role="group" aria-label="渡す数">${Object.entries(procedureAmounts).map(([k,v])=>`<button data-sp-amount="${k}" aria-pressed="${q.amount===k}">${v}${q.trials[`${q.role}:${k}`].checked?' ✓':''}</button>`).join('')}</div><div class="scenario-selector" role="group" aria-label="結果の予想">${Object.entries(procedureAnswers).map(([k,v])=>`<button data-sp-guess="${k}" aria-pressed="${t.guess===k}">${v}</button>`).join('')}</div><button id="sp-check">手続きを呼び出す</button><p role="status">${procedureMessage}</p>${t.checked?`<p>結果：${procedureAnswers[procedureOutcome(q.role,q.amount)]}。</p>`:''}<details><summary>手がかり</summary><p>まず呼び出せる人かを確認し、呼び出せる場合は渡した数と５束を比べます。</p></details></section><section class="panel"><h2>手続きの置き場所を振り返る</h2><p>四つの条件を試し、同じ手続きに異なる値を渡したときの説明を選びましょう。</p><div class="scenario-selector" role="group" aria-label="振り返り"><button data-sp-reflection="shared" aria-pressed="${q.reflection==='shared'}">同じ手続きを呼び出し、渡す数に応じた処理を行う</button><button data-sp-reflection="permission" aria-pressed="${q.reflection==='permission'}">手続きが保存されていれば、誰でも必ず呼び出せる</button></div></section>${done?'<section class="result panel"><h2>薬草庫へ依頼を届けました！</h2><p>保存された手続きは異なる引数で繰り返し呼び出せます。実行権限の確認と、手続き内の在庫条件は別の段階です。</p><p>固定された模型で、実際のデータベース、同時実行、権限設定やトランザクションの設計は評価しません。</p><button id="return">ギルドへ戻る</button></section>':''}<aside class="reference">学びの手がかり：<a href="https://www.postgresql.org/docs/current/sql-createprocedure.html" target="_blank" rel="noopener noreferrer">PostgreSQL：手続きの定義 ↗</a> ／ <a href="https://www.postgresql.org/docs/current/sql-call.html" target="_blank" rel="noopener noreferrer">呼び出し ↗</a></aside></div>`;
 const update=()=>{writeDraft(active.id,q);if(procedureDone(q)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderStoredProcedure();};
 app.querySelector('#back').onclick=renderHome;
 app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);procedureQuest=procedureCreate();procedureMessage='';renderStoredProcedure();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-sp-role]').forEach(b=>b.onclick=()=>{q.role=b.dataset.spRole;procedureMessage='';update();app.querySelector(`[data-sp-role="${q.role}"]`).focus();});
 app.querySelectorAll('[data-sp-amount]').forEach(b=>b.onclick=()=>{q.amount=b.dataset.spAmount;procedureMessage='';update();app.querySelector(`[data-sp-amount="${q.amount}"]`).focus();});
 app.querySelectorAll('[data-sp-guess]').forEach(b=>b.onclick=()=>{const id=b.dataset.spGuess;t.guess=id;t.checked=false;procedureMessage='';update();app.querySelector(`[data-sp-guess="${id}"]`).focus();});
 app.querySelector('#sp-check').onclick=()=>{try{procedureMessage=procedureCheck(q)?'予想が合いました。':'呼出し権限と、渡す数・在庫を確認しましょう。';}catch(e){procedureMessage=e.message;}update();app.querySelector('#sp-check').focus();};
 app.querySelectorAll('[data-sp-reflection]').forEach(b=>b.onclick=()=>{q.reflection=b.dataset.spReflection;procedureMessage=q.reflection==='shared'?'同じ手続きに値を渡せます。':'呼出しには権限が必要です。';update();app.querySelector(`[data-sp-reflection="${q.reflection}"]`).focus();});
 if(done)app.querySelector('#return').onclick=renderHome;
}
function renderCommunicationsExpedition(){
 const q=serviceJourneyQuest,s=serviceJourneyReplay(q.history),yes=v=>v?'（試験済み）':'';
 app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow">QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div></div><section class="panel"><h2>${serviceJourneyPlaces[s.place]}</h2>${draftMessage()}<p>南村の依頼 → 受付の依頼 → ギルドへの報告。前に訪れた場所へ戻ることもできます。</p><p role="status">${serviceJourneyMessage||s.last}</p>${s.place==='village'?`<p>南村の薬師：「伝令が途切れても、この端末にある２束の記録を開きたい」</p><p>依頼1290と同じ固定例です。共有サービスの遠隔記録は５束、端末内の別記録は２束。この共有サービスには通信断用の控えがなく、端末の道具には共有記録との自動同期がありません。実製品には別の機能もあります。</p>${s.villageDone?'<p>端末内の道具を南村に届けました。共有記録とは別なので、５束を見たことにはなりません。</p>':`<div class="scenario-selector" role="group" aria-label="南村の方式">${Object.entries(saasModes).map(([k,v])=>`<button data-cj-mode="${k}" aria-pressed="${s.mode===k}">${v}</button>`).join('')}</div><div class="robot-actions" role="group" aria-label="南村の通信試験">${Object.entries(saasNetworks).map(([k,v])=>`<button data-cj-network="${k}">${v}を試す${yes(s.networks.includes(k))}</button>`).join('')}</div><button id="cj-confirm-village">南村に方式を届ける</button>`}`:s.place==='office'?`<p>受付係：「注文側の作業場が停止しても、注文先に問い合わせない報告は続けたい。共通の門の限界も調べてほしい」</p><p>依頼1291と同じ固定例です。一体型は二つの仕事を一つの作業場で扱い、分割型は別々に動かします。両方とも共通の門を通り、分割型の報告は注文側に問い合わせません。注文側の故障は、その仕事が属する作業場全体の停止です。</p>${s.officeDone?'<p>分割した作業場を届けました。共通の門の停止では両方に到達できません。</p>':`<div class="scenario-selector" role="group" aria-label="受付の構成">${Object.entries(serviceDesignModes).map(([k,v])=>`<button data-cj-design="${k}" aria-pressed="${s.design===k}">${v}</button>`).join('')}</div><div class="robot-actions" role="group" aria-label="受付の試験">${Object.entries(serviceDesignFaults).map(([k,v])=>`<button data-cj-fault="${k}">${v}を試す${yes(s.faults.includes(k))}</button>`).join('')}</div><button id="cj-confirm-office">受付に構成を届ける</button>`}`:`<p>二つの場所を巡りました。最後に、共通の門について報告しましょう。</p><div class="scenario-selector" role="group" aria-label="共通の門の報告"><button data-cj-reflection="shared" aria-pressed="${s.reflection==='shared'}">門が止まれば、分割していても両方に到達できない</button><button data-cj-reflection="immune" aria-pressed="${s.reflection==='immune'}">分割すれば、門が止まっても両方使える</button></div><button id="cj-report" ${s.won?'disabled':''}>遠征を報告する</button>`}<div class="robot-actions"><button data-cj-move="back" ${s.place==='village'||s.won?'disabled':''}>前の場所へ</button><button data-cj-move="next" ${s.place==='guild'||s.won?'disabled':''}>次の場所へ</button></div></section>${s.won?'<section class="result panel"><h2>二つの場所に仕組みを届けました！</h2><p>南村では通信が切れても端末内の記録を読み、受付では注文作業場の停止と共通の門の停止を区別しました。</p><p>通信断用の控えがない共有サービスと、自動同期しない端末の道具を仮定した例です。受付の報告は注文側に依存せず、門は共有と仮定します。実製品の機能、他の故障、同期や実際の安全性は評価しません。</p><button id="return">ギルドへ戻る</button></section>':''}<aside class="reference">学びの手がかり：<a href="https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-145.pdf" target="_blank" rel="noopener noreferrer">NIST：SaaS ↗</a> ／ <a href="https://learn.microsoft.com/en-us/azure/architecture/microservices/" target="_blank" rel="noopener noreferrer">Microsoft：マイクロサービス ↗</a></aside></div>`;
 const cap=q.capacity,rows=capacityTrace(cap.mode,cap.ticks[cap.mode]),sum=k=>rows.reduce((n,r)=>n+r[k],0),extra=document.createElement('section');extra.className='panel search-panel';extra.innerHTML=`<h2>追加の依頼：混雑する受付</h2><p>４刻の到着数は ${capacityDemand.join('、')} 件。受付係１人は１刻に３件まで処理し、この模型では超えた分は待たずに断られます。１人・１刻の費用を１とします。</p><p>自動調整では最初は１人で、各刻の需要から必要人数を決め、次の刻に反映します。３方式を最後まで試して比べましょう。</p><div class="scenario-selector" role="group" aria-label="受付係の増やし方">${Object.entries(capacityModes).map(([k,v])=>`<button data-capacity-mode="${k}" aria-pressed="${cap.mode===k}">${v}${cap.ticks[k]===4?' ✓':''}</button>`).join('')}</div><button id="capacity-step" ${cap.ticks[cap.mode]===4?'disabled':''}>次の１刻を試す</button> <button id="capacity-reset">この方式を最初から</button><p role="status">${rows.length?rows.map(r=>`${r.tick}刻：到着${r.demand}件、係${r.workers}人、処理${r.served}件、断り${r.lost}件`).join(' ／ '):'まだ試していません。'}</p><p>この方式の合計：断り ${sum('lost')} 件、費用 ${sum('cost')}。</p><h3>受付係の振り返り</h3><p>自動調整を使っても急な混雑の初めに断りが出るのはなぜ？</p><div class="scenario-selector" role="group" aria-label="混雑の振り返り"><button data-capacity-answer="delay" aria-pressed="${cap.answer==='delay'}">需要を見てから次の刻に人数を変えるから</button><button data-capacity-answer="perfect" aria-pressed="${cap.answer==='perfect'}">人数が必ず需要を先読みするから</button><button data-capacity-answer="free" aria-pressed="${cap.answer==='free'}">係を増やしても費用がかからないから</button></div><p role="status">${cap.answer&&cap.answer!=='delay'?'到着数と人数がいつ変わるか見直しましょう。':capacityComplete(cap)?'３方式を比較しました。１人固定は費用４・断り８、３人固定は費用12・断り０、自動調整は費用８・断り４です。':'３方式を最後まで試し、振り返りを選びましょう。'}</p><p>これは到着数・処理能力・反応速度・単価を固定した模型です。実際のサービスでは待ち行列、起動時間、上限、料金体系、共有部分の負荷や障害も考える必要があります。</p><p><a href="https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-default-instance-warmup.html" target="_blank" rel="noopener noreferrer">AWS：自動調整と起動後の時間 ↗</a></p>`;app.querySelector('.reference').before(extra);
 extra.querySelectorAll('[data-capacity-mode]').forEach(b=>b.onclick=()=>{cap.mode=b.dataset.capacityMode;writeDraft(active.id,q);renderCommunicationsExpedition();app.querySelector(`[data-capacity-mode="${cap.mode}"]`).focus();});
 extra.querySelector('#capacity-step').onclick=()=>{cap.ticks[cap.mode]++;writeDraft(active.id,q);renderCommunicationsExpedition();(app.querySelector('#capacity-step').disabled?app.querySelector('#capacity-reset'):app.querySelector('#capacity-step')).focus();};
 extra.querySelector('#capacity-reset').onclick=()=>{cap.ticks[cap.mode]=0;writeDraft(active.id,q);renderCommunicationsExpedition();app.querySelector('#capacity-reset').focus();};
 extra.querySelectorAll('[data-capacity-answer]').forEach(b=>b.onclick=()=>{cap.answer=b.dataset.capacityAnswer;writeDraft(active.id,q);renderCommunicationsExpedition();app.querySelector(`[data-capacity-answer="${cap.answer}"]`).focus();});
 const g=cap.gate,gr=capacityGateResult(g.workers,g.limit),gate=document.createElement('section');gate.className='panel search-panel';gate.innerHTML=`<h2>受付の手前にある門</h2><p>混雑時の到着は７件。全員が共通の門を通ってから受付に向かいます。受付係１人は３件を処理でき、門は１刻に４件または９件を通せます。門と係を通れなかった件は断られるものとします。</p><div class="scenario-selector" role="group" aria-label="受付係の人数">${[1,3].map(n=>`<button data-gate-workers="${n}" aria-pressed="${g.workers===n}">受付係 ${n} 人</button>`).join('')}</div><div class="scenario-selector" role="group" aria-label="門の通過上限">${[4,9].map(n=>`<button data-gate-limit="${n}" aria-pressed="${g.limit===n}">門の上限 ${n} 件</button>`).join('')}</div><button id="gate-run">この組み合わせを試す</button><p role="status">${g.checked?`処理 ${gr.served} 件、断り ${gr.lost} 件。受付係の費用 ${gr.cost}。`:'人数と門を選んで試しましょう。'}</p><p>試した組み合わせ：${g.seen.length} / 4。</p><h3>門が４件までの場合</h3><p>３人に増やしても７件すべてを処理できないとき、次に何を調べますか。</p><div class="scenario-selector" role="group" aria-label="次に調べる場所"><button data-gate-answer="gate" aria-pressed="${g.answer==='gate'}">共通の門の上限</button><button data-gate-answer="workers" aria-pressed="${g.answer==='workers'}">受付係だけをさらに増やす</button><button data-gate-answer="none" aria-pressed="${g.answer==='none'}">どこも調べず処理できたとみなす</button></div><p role="status">${g.answer&&g.answer!=='gate'?'門と受付の両方の上限を比べましょう。':capacityGateComplete(g)?'４通りを比べました。係３人では門が４件なら処理４件、門が９件なら７件です。共通の部分が全体の処理を制限することがあります。':'４通りを試して、次に調べる場所を選びましょう。'}</p><p>費用は係の人数だけを数えた架空の値で、門の費用は含みません。実際のシステムには他の制約や待ち時間があり、計測が必要です。</p><p><a href="https://learn.microsoft.com/en-us/azure/architecture/best-practices/auto-scaling" target="_blank" rel="noopener noreferrer">Microsoft：自動調整と処理の制約 ↗</a></p>`;app.querySelector('.reference').before(gate);
 gate.querySelectorAll('[data-gate-workers],[data-gate-limit]').forEach(b=>b.onclick=()=>{const isWorkers=b.hasAttribute('data-gate-workers'),field=isWorkers?'workers':'limit',value=Number(b.getAttribute(`data-gate-${field}`));g[field]=value;g.checked=false;writeDraft(active.id,q);renderCommunicationsExpedition();app.querySelector(`[data-gate-${field}="${value}"]`).focus();});
 gate.querySelector('#gate-run').onclick=()=>{const key=`${g.workers}:${g.limit}`;if(!g.seen.includes(key))g.seen.push(key);g.checked=true;writeDraft(active.id,q);renderCommunicationsExpedition();app.querySelector('#gate-run').focus();};
 gate.querySelectorAll('[data-gate-answer]').forEach(b=>b.onclick=()=>{g.answer=b.dataset.gateAnswer;writeDraft(active.id,q);renderCommunicationsExpedition();app.querySelector(`[data-gate-answer="${g.answer}"]`).focus();});
 const perform=(action,selector,failureSelector=selector)=>{let target=selector;try{const state=serviceJourneyAct(q,action);serviceJourneyMessage=state.last;writeDraft(active.id,q);if(state.won){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable&&Object.values(cap.ticks).every(n=>n===0)&&cap.answer===null&&g.workers===1&&g.limit===4&&g.seen.length===0&&g.answer===null)clearDraft(active.id);}}catch(e){serviceJourneyMessage=e.message;target=failureSelector;}renderCommunicationsExpedition();(app.querySelector(target+':not(:disabled)')||app.querySelector('#return')||app.querySelector('#back')).focus();};
 app.querySelector('#back').onclick=renderHome;app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);serviceJourneyQuest=serviceJourneyCreate();serviceJourneyMessage='';renderCommunicationsExpedition();app.querySelector('#reset-draft').focus();};
 app.querySelectorAll('[data-cj-mode]').forEach(b=>b.onclick=()=>perform(`mode:${b.dataset.cjMode}`,`[data-cj-mode="${b.dataset.cjMode}"]`));app.querySelectorAll('[data-cj-network]').forEach(b=>b.onclick=()=>perform(`network:${b.dataset.cjNetwork}`,`[data-cj-network="${b.dataset.cjNetwork}"]`));app.querySelectorAll('[data-cj-design]').forEach(b=>b.onclick=()=>perform(`design:${b.dataset.cjDesign}`,`[data-cj-design="${b.dataset.cjDesign}"]`));app.querySelectorAll('[data-cj-fault]').forEach(b=>b.onclick=()=>perform(`fault:${b.dataset.cjFault}`,`[data-cj-fault="${b.dataset.cjFault}"]`));app.querySelectorAll('[data-cj-reflection]').forEach(b=>b.onclick=()=>perform(`reflection:${b.dataset.cjReflection}`,`[data-cj-reflection="${b.dataset.cjReflection}"]`));app.querySelectorAll('[data-cj-move]').forEach(b=>b.onclick=()=>perform(b.dataset.cjMove,`[data-cj-move="${b.dataset.cjMove}"]`));app.querySelector('#cj-confirm-village')?.addEventListener('click',()=>perform('confirm:village','[data-cj-move="next"]','#cj-confirm-village'));app.querySelector('#cj-confirm-office')?.addEventListener('click',()=>perform('confirm:office','[data-cj-move="next"]','#cj-confirm-office'));app.querySelector('#cj-report')?.addEventListener('click',()=>perform('report','#cj-report'));if(s.won)app.querySelector('#return').onclick=renderHome;
}
